/**
 * Motion blur on a planet, as numbers. The GPU pass (motionBlurChunk.ts)
 * does this arithmetic per pixel, with these constants.
 *
 * Only the camera's own motion blurs: each pixel's point is found again from
 * the depth, and the camera of the frame before says where it was drawn then
 * (temporal.ts `reprojection`), so a turn moves the whole picture and fast
 * flight streaks the near ground most. The picture is smeared along that
 * motion by the shutter's share of it, held to a short most.
 *
 * It is a comfort setting: the visitor's choice, off unless they turn it on,
 * never in VR, and drawn only where the picture moves fast. Slow looking
 * about and walking stay sharp. How fast is read per second, not per frame,
 * so a slow frame does not blur where a quick one would not.
 *
 * Pure: no Babylon, no DOM.
 */
import type { MotionBlurChoice } from '../../settings/quality';

export const MOTION_BLUR = {
  /** The share of a frame's motion the streak covers (a 180 degree shutter). */
  shutter: 0.5,
  /** No blur below this speed, as a share of the screen's height each sixtieth of a second; all of it from `fullShare`. */
  startShare: 0.012,
  fullShare: 0.03,
  /** The longest streak, as a share of the screen's height. */
  maxShare: 0.025,
  /** Samples along a streak. */
  samples: 8,
} as const;

/** Whether the blur is drawn at all: the visitor turned it on, and they are not presenting in VR. */
export function motionBlurWanted(choice: MotionBlurChoice | undefined, presenting: boolean): boolean {
  return choice === 'on' && !presenting;
}

/** How much a pixel blurs, 0 to 1, from how far it moved on the screen since the frame before (`movedPx`), the time between (`dtS`) and the screen's height. */
export function blurWeight(movedPx: number, dtS: number, heightPx: number): number {
  if (!(dtS > 0) || !(heightPx > 0)) return 0;
  const speed = (movedPx / heightPx) * (1 / 60 / dtS);
  const t = (speed - MOTION_BLUR.startShare) / (MOTION_BLUR.fullShare - MOTION_BLUR.startShare);
  const x = Math.min(1, Math.max(0, t));
  return x * x * (3 - 2 * x);
}

/** The length of a pixel's streak on the screen, from how far it moved since the frame before. */
export function streakPx(movedPx: number, heightPx: number): number {
  return Math.min(movedPx * MOTION_BLUR.shutter, MOTION_BLUR.maxShare * heightPx);
}

/**
 * How far a point drawn now at `ndc` (its place on the screen, -1 to 1, and
 * its depth as the projection gives it) has moved since the frame before, in
 * the same units: `reproject` is temporal.ts `reprojection`, a row vector on
 * the left.
 */
export function motionAt(reproject: readonly number[], ndc: [number, number, number]): [number, number] {
  const [x, y, z] = ndc;
  const m = reproject;
  const bx = x * m[0]! + y * m[4]! + z * m[8]! + m[12]!;
  const by = x * m[1]! + y * m[5]! + z * m[9]! + m[13]!;
  const bw = x * m[3]! + y * m[7]! + z * m[11]! + m[15]!;
  if (!(bw > 0)) return [0, 0];
  return [x - bx / bw, y - by / bw];
}
