/**
 * Motion blur on a planet — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the pass below,
 * loaded only by dynamic `import()` from the planet view
 * (contactAndBlur.ts), once the visitor turns motion blur on; never in VR.
 *
 * One pass over the whole picture, after the temporal anti-aliasing and the
 * contact shadows and before the eye exposes it (screenPasses.ts). Each
 * pixel's point is found again from the depth the scene was drawn with, and
 * the camera of the frame before says where it was drawn then
 * (temporal.ts `reprojection`): only the camera's own motion blurs. Where the
 * picture moves fast, a turn or fast flight, the pixel is smeared along that
 * motion by the shutter's share of it (motionBlur.ts has the arithmetic);
 * slower, it is copied as it is. A jump, as when the visitor is moved, or
 * the first frame, blurs nothing. As the other planet passes, it is written
 * in WGSL for WebGPU and GLSL for WebGL2, kept in step.
 */
import { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ShaderStore } from '@babylonjs/core/Engines/shaderStore';
import { Constants } from '@babylonjs/core/Engines/constants';
import { Matrix } from '@babylonjs/core/Maths/math.vector';
import type { Effect } from '@babylonjs/core/Materials/effect';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { Scene } from '@babylonjs/core/scene';
import type { MotionBlurHandle } from './contactAndBlur';
import { MOTION_BLUR } from './motionBlur';
import { continuous, reprojection, type CameraPose } from './temporal';
import { depthNdcOf, giveDepthIfFirst, keepInOrder, sceneDepth } from './screenPasses';

const f = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

const NAME = 'planetMotionBlur';
/** Babylon's `Camera.PERSPECTIVE_CAMERA`, written out so the chunk takes the camera's type alone. */
const PERSPECTIVE = 0;

const GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform highp sampler2D depthSampler;
uniform mat4 reprojection;
uniform vec2 depthNdc;
uniform vec2 screen;
uniform float dt;
uniform float live;
vec4 blurred(vec2 uv, vec4 colour) {
  if (live < 0.5) return colour;
  ivec2 size = textureSize(depthSampler, 0);
  float d = texelFetch(depthSampler, clamp(ivec2(uv * vec2(size)), ivec2(0), size - 1), 0).r;
  vec4 before = reprojection * vec4(uv * 2.0 - 1.0, d * depthNdc.x + depthNdc.y, 1.0);
  if (before.w <= 0.0) return colour;
  vec2 moved = (uv * 2.0 - 1.0 - before.xy / before.w) * 0.5 * screen;
  float px = length(moved);
  float w = smoothstep(${f(MOTION_BLUR.startShare)}, ${f(MOTION_BLUR.fullShare)}, px / screen.y * (${f(1 / 60)} / dt));
  if (w <= 0.0) return colour;
  float streak = min(px * ${f(MOTION_BLUR.shutter)}, ${f(MOTION_BLUR.maxShare)} * screen.y) * w;
  vec2 along = moved / max(px, 0.0001) * streak / screen;
  vec3 sum = vec3(0.0);
  for (int k = 0; k < ${MOTION_BLUR.samples}; k++) sum += texture2D(textureSampler, uv + along * ((float(k) + 0.5) / ${f(MOTION_BLUR.samples)} - 0.5)).rgb;
  return vec4(sum / ${f(MOTION_BLUR.samples)}, colour.a);
}
void main(void) {
  gl_FragColor = blurred(vUV, texture2D(textureSampler, vUV));
}`;

const WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
var depthSampler: texture_depth_2d;
uniform reprojection: mat4x4f;
uniform depthNdc: vec2f;
uniform screen: vec2f;
uniform dt: f32;
uniform live: f32;
fn blurred(uv: vec2f, colour: vec4f) -> vec4f {
  if (uniforms.live < 0.5) { return colour; }
  let size = vec2i(textureDimensions(depthSampler, 0));
  let d = textureLoad(depthSampler, clamp(vec2i(uv * vec2f(size)), vec2i(0), size - 1), 0);
  let before = uniforms.reprojection * vec4f(uv * 2.0 - 1.0, d * uniforms.depthNdc.x + uniforms.depthNdc.y, 1.0);
  if (before.w <= 0.0) { return colour; }
  let moved = (uv * 2.0 - 1.0 - before.xy / before.w) * 0.5 * uniforms.screen;
  let px = length(moved);
  let w = smoothstep(${f(MOTION_BLUR.startShare)}, ${f(MOTION_BLUR.fullShare)}, px / uniforms.screen.y * (${f(1 / 60)} / uniforms.dt));
  if (w <= 0.0) { return colour; }
  let streak = min(px * ${f(MOTION_BLUR.shutter)}, ${f(MOTION_BLUR.maxShare)} * uniforms.screen.y) * w;
  let along = moved / max(px, 0.0001) * streak / uniforms.screen;
  var sum = vec3f(0.0);
  for (var k = 0; k < ${MOTION_BLUR.samples}; k++) {
    sum += textureSampleLevel(textureSampler, textureSamplerSampler, uv + along * ((f32(k) + 0.5) / ${f(MOTION_BLUR.samples)} - 0.5), 0.0).rgb;
  }
  return vec4f(sum / ${f(MOTION_BLUR.samples)}, colour.a);
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  fragmentOutputs.color = blurred(input.vUV, textureSampleLevel(textureSampler, textureSamplerSampler, input.vUV, 0.0));
}`;

export function createMotionBlur(scene: Scene, camera: Camera, opts: { engineKind?: string }): MotionBlurHandle {
  const engine = scene.getEngine();
  const wgsl = opts.engineKind === 'webgpu';
  const language = wgsl ? ShaderLanguage.WGSL : ShaderLanguage.GLSL;
  const store = wgsl ? ShaderStore.ShadersStoreWGSL : ShaderStore.ShadersStore;
  store[`${NAME}PixelShader`] ??= wgsl ? WGSL : GLSL;

  const pass = new PostProcess(NAME, NAME, {
    engine,
    size: 1,
    uniforms: ['reprojection', 'depthNdc', 'screen', 'dt', 'live'],
    samplers: ['depthSampler'],
    samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE,
    textureType: Constants.TEXTURETYPE_HALF_FLOAT,
    shaderLanguage: language,
  });
  camera.attachPostProcess(pass);
  keepInOrder(camera);

  const ordering: Observer<Camera> = scene.onBeforeCameraRenderObservable.add((cam) => {
    if (cam === camera) keepInOrder(camera);
  });
  pass.onActivateObservable.add(() => giveDepthIfFirst(camera, pass));

  let dtS = 0;
  let before: CameraPose | null = null;
  const reproject = new Matrix();
  pass.onApplyObservable.add((effect: Effect) => {
    const depth = sceneDepth(camera);
    if (depth) effect._bindTexture('depthSampler', depth);
    const view = camera.getViewMatrix().m;
    const p = camera.globalPosition;
    // The projection as the scene was drawn: its jitter, where the anti-aliasing moved it, kept apart.
    const projection = [...camera.getProjectionMatrix().m];
    const jitter: [number, number] = camera.mode === PERSPECTIVE ? [projection[8]!, projection[9]!] : [0, 0];
    projection[8] = 0;
    projection[9] = 0;
    const now: CameraPose = {
      position: [p.x, p.y, p.z],
      rotation: [view[0]!, view[1]!, view[2]!, view[4]!, view[5]!, view[6]!, view[8]!, view[9]!, view[10]!],
      projection,
    };
    const live = depth !== null && before !== null && dtS > 0 && continuous(before.position, now.position);
    Matrix.FromArrayToRef(reprojection(now, jitter, before ?? now), 0, reproject);
    effect.setMatrix('reprojection', reproject);
    const [a, b] = depthNdcOf(engine.isNDCHalfZRange);
    effect.setFloat2('depthNdc', a, b);
    effect.setFloat2('screen', pass.width, pass.height);
    effect.setFloat('dt', dtS > 0 ? dtS : 1 / 60);
    effect.setFloat('live', live ? 1 : 0);
    before = now;
  });

  return {
    update(frame) {
      dtS = frame.dtS;
    },
    dispose() {
      scene.onBeforeCameraRenderObservable.remove(ordering);
      camera.detachPostProcess(pass);
      pass.dispose(camera);
    },
  };
}
